import{_ as t,o as a,c as n,ae as i}from"./chunks/framework.B2FZg54p.js";const r="/heidrun/experiments/web-doc-by-ai/documentation_images/find_terminal_output/search_field_and_filters.svg",s="/heidrun/experiments/web-doc-by-ai/documentation_images/find_terminal_output/select_a_matching_line.svg",g=JSON.parse('{"title":"Find text in terminal output","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/find_terminal_output.md","filePath":"documentation/find_terminal_output.md"}'),o={name:"documentation/find_terminal_output.md"};function l(h,e,c,u,p,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="find-text-in-terminal-output" tabindex="-1">Find text in terminal output <a class="header-anchor" href="#find-text-in-terminal-output" aria-label="Permalink to &quot;Find text in terminal output&quot;">​</a></h1><p>Search recent terminal output, then select a matching line to return to its pane.</p><h2 id="search-the-terminals" tabindex="-1">Search the terminals <a class="header-anchor" href="#search-the-terminals" aria-label="Permalink to &quot;Search the terminals&quot;">​</a></h2><p>A pane is one terminal inside a tab.</p><ol><li>Press <strong>Command+Shift+F</strong> to open <strong>Search in the terminals</strong>. Alternatively, click <strong>Search, run a command…</strong> in the top bar or press <strong>Command+K</strong> to open the command palette, then choose <strong>Search in all terminals…</strong>.</li><li>Enter at least two characters in the search field. Plain text searches ignore letter case and accents; leave <code>.*</code> (<strong>Regular expression</strong>) unchecked when punctuation should be treated as ordinary text.</li><li>Check the current filter settings before reading the results. <strong>This workspace</strong> limits results to the selected workspace; when it is unchecked, panes across workspaces are searched. <strong>Agents only</strong> excludes ordinary shell panes, and <code>.*</code> (<strong>Regular expression</strong>) changes how the search text is interpreted; these settings are remembered.</li></ol><p><img src="'+r+'" alt="Search text and check the current filters in Search in the terminals"></p><p>Results are grouped by pane name and show matching lines with nearby terminal text. The search checks up to 3,000 recent lines from each current pane; it does not search project files or an unlimited archive. The number of results counts matching lines, including command echoes, so it may be larger than the number of commands that printed the text.</p><h2 id="open-a-matching-line" tabindex="-1">Open a matching line <a class="header-anchor" href="#open-a-matching-line" aria-label="Permalink to &quot;Open a matching line&quot;">​</a></h2><ol><li>Find the pane group that contains the line you want.</li><li>Select the matching line itself, rather than the pane group heading. Search closes and Heidrun selects the workspace, tab and pane that own the line.</li></ol><p><img src="'+s+'" alt="Select a matching line in its pane group"></p><p>Heidrun attempts to scroll to and highlight the matching text when that line is still available in the pane. If the text is no longer available, the pane may not show the match.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="No results appear"><h3 id="no-results-appear" tabindex="-1">No results appear <a class="header-anchor" href="#no-results-appear" aria-label="Permalink to &quot;No results appear&quot;">​</a></h3><p><strong>Cause:</strong> The query is too short, the text is absent from recent pane output, or a filter excludes the pane or changes how punctuation is read.</p><p><strong>Solution:</strong></p><ol><li>Enter at least two characters and check the spelling against the terminal output.</li><li>Check whether <strong>This workspace</strong> is limiting results to the selected workspace.</li><li>Clear <strong>Agents only</strong> if the output came from an ordinary shell pane.</li><li>Clear <code>.*</code> (<strong>Regular expression</strong>) if you want punctuation to match literally.</li></ol><p><strong>Check:</strong> Matching lines appear beneath their pane group when the text is in the searched output and the filters include that pane.</p></section><section class="documentation-troubleshooting-topic" aria-label="The latest terminal output is missing"><h3 id="the-latest-terminal-output-is-missing" tabindex="-1">The latest terminal output is missing <a class="header-anchor" href="#the-latest-terminal-output-is-missing" aria-label="Permalink to &quot;The latest terminal output is missing&quot;">​</a></h3><p><strong>Cause:</strong> The search can reuse output already read while the dialog is open, and it cannot search beyond the recent history available from each pane.</p><p><strong>Solution:</strong></p><ol><li>Press <strong>Escape</strong> to close <strong>Search in the terminals</strong>, then press <strong>Command+Shift+F</strong> to reopen it and refresh the output used by the search.</li><li>Search for a distinctive phrase from the recent output, which must still be in the pane&#39;s available history.</li></ol><p><strong>Check:</strong> The refreshed search shows a matching line if the line remains in the pane&#39;s available recent output.</p></section><section class="documentation-troubleshooting-topic" aria-label="The selected result is higher in the history"><h3 id="the-selected-result-is-higher-in-the-history" tabindex="-1">The selected result is higher in the history <a class="header-anchor" href="#the-selected-result-is-higher-in-the-history" aria-label="Permalink to &quot;The selected result is higher in the history&quot;">​</a></h3><p><strong>Cause:</strong> Heidrun could not find the selected line in the pane&#39;s currently available terminal history to scroll to and highlight it.</p><p><strong>Solution:</strong></p><ol><li>Scroll up in the selected pane to look for the matching line in its earlier output.</li></ol><p><strong>Check:</strong> The matching line is visible in the pane if it remains in the available terminal history.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to look up the search shortcut and other keys.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/split_and_resize_panes.html">Split and resize panes</a>: to work with the pane that contains a result.</li></ul>',17)])])}const b=t(o,[["render",l]]);export{g as __pageData,b as default};
